    left, right = min(all_cols), max(all_cols)

    # Rows with several marks, plus the outermost marked rows, form
    # horizontal strokes spanning the object's overall width.
    horizontal_rows = set()
    for r in active_rows:
        if sum(v == mark for v in grid[r]) >= 3:
            horizontal_rows.add(r)
    horizontal_rows.update((top, bottom))

    for r in horizontal_rows:
        for c in range(left, right + 1):
            if grid[r][c] == bg:
                out[r][c] = 2

    # Complete the outer sides. Interior repeated columns are also
    # strokes when they include marks away from horizontal rows.
    for c in range(left, right + 1):
        rows = [r for r in range(h) if grid[r][c] == mark]
        is_outer = c == left or c == right
        is_vertical = len(rows) >= 3 and any(r not in horizontal_rows for r in rows)
        if is_outer or is_vertical:
            for r in range(top, bottom + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

